CREATE TABLE IF NOT EXISTS notification_escalation_policy(id SMALLINT PRIMARY KEY CHECK(id=1),enabled BOOLEAN NOT NULL DEFAULT TRUE,warning_interval_minutes INTEGER NOT NULL DEFAULT 30 CHECK(warning_interval_minutes BETWEEN 5 AND 1440),critical_interval_minutes INTEGER NOT NULL DEFAULT 10 CHECK(critical_interval_minutes BETWEEN 1 AND 1440),max_reminders INTEGER NOT NULL DEFAULT 3 CHECK(max_reminders BETWEEN 1 AND 20),critical_escalate_after_minutes INTEGER NOT NULL DEFAULT 20 CHECK(critical_escalate_after_minutes BETWEEN 1 AND 10080),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_by TEXT REFERENCES platform_users(id) ON DELETE SET NULL);
INSERT INTO notification_escalation_policy(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS notification_escalations(id TEXT PRIMARY KEY,alert_event_id TEXT NOT NULL REFERENCES alert_events(id) ON DELETE CASCADE,reminder_number INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','sent','failed','suppressed','no_channel')),escalated BOOLEAN NOT NULL DEFAULT FALSE,delivery_count INTEGER NOT NULL DEFAULT 0,detail TEXT,attempted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(alert_event_id,reminder_number));
CREATE INDEX IF NOT EXISTS notification_escalations_time_idx ON notification_escalations(attempted_at DESC);
